// Sine wave lookup table values (1/2 cycle, 32 samples)
const uint8_t spwmTable[] PROGMEM = {
  0, 24, 49, 74, 97, 120, 141, 161, 
  180, 197, 212, 224, 235, 242, 247, 250, 
  250, 247, 242, 235, 224, 212, 197, 180, 
  161, 141, 120, 97, 74, 49, 24, 0
};

// Interrupt service routine for high-frequency SPWM switching
ISR(TIMER1_COMPA_vect) {
  static uint8_t index = 0;
  static boolean halfCycle = false;

  if (halfCycle) {
    OCR1A = spwmTable[index]; // Set positive half-cycle pulse width
    OCR1B = 0;
  } else {
    OCR1A = 0;
    OCR1B = spwmTable[index]; // Set negative half-cycle pulse width
  }

  index++;
  if (index >= 32) {
    index = 0;
    halfCycle = !halfCycle; // Toggle polarity
  }
}
